import{f as o,o as a,c as r,a2 as i}from"./chunks/framework.Cd9rfTEn.js";const p=JSON.parse('{"title":"Fichas de integraciones externas","description":"","frontmatter":{},"headers":[],"relativePath":"relevamiento/integraciones-fichas.md","filePath":"relevamiento/integraciones-fichas.md","lastUpdated":null}'),t={name:"relevamiento/integraciones-fichas.md"};function n(c,e,s,d,l,u){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="fichas-de-integraciones-externas" tabindex="-1">Fichas de integraciones externas <a class="header-anchor" href="#fichas-de-integraciones-externas" aria-label="Permalink to &quot;Fichas de integraciones externas&quot;">​</a></h1><p>Versión: 0.1 (borrador para validar) Fecha: 3/11/2026 Complementa la sección 30 (Módulo 29 — Integraciones externas) de <a href="./definicion-funcional-alcance">definicion-funcional-alcance.md</a>.</p><h2 id="_0-como-leer-este-documento" tabindex="-1">0. Cómo leer este documento <a class="header-anchor" href="#_0-como-leer-este-documento" aria-label="Permalink to &quot;0. Cómo leer este documento&quot;">​</a></h2><p>Cada ficha describe una integración que el sistema nuevo necesita para reemplazar a Procoop: qué intercambia, por qué medio, cada cuánto, de qué módulos depende y qué falta averiguar.</p><p><strong>Marcas de evidencia:</strong> se usan las mismas del documento de alcance ([P] pantalla, [M] menú, [T] tabla, [I] inferido) más una nueva:</p><table tabindex="0"><thead><tr><th>Marca</th><th>Significado</th></tr></thead><tbody><tr><td><strong>[B]</strong></td><td>Clase o método encontrado en los binarios de producción, sobre todo en <code>ReglasNegocio.dll</code> (ver <a href="./binarios/inventarios/ReglasNegocio"><code>binarios/inventarios/ReglasNegocio.md</code></a>). Indica que Procoop <em>soporta</em> la integración, no que Laguna Larga la <em>use</em>.</td></tr></tbody></table><p><strong>Prioridades:</strong> A, B y C con el mismo significado que en el alcance (A = imprescindible para el paralelo; B = necesaria para el by pass; C = diferible).</p><p><strong>Campos de cada ficha:</strong></p><ul><li><strong>Dirección:</strong> saliente (el sistema envía), entrante (el sistema recibe) o bidireccional.</li><li><strong>Medio:</strong> servicio web (SOAP o REST), archivo (TXT de ancho fijo, CSV, Excel) o dispositivo.</li><li><strong>Frecuencia:</strong> cuándo se dispara.</li><li><strong>Depende de:</strong> módulos del alcance que la necesitan o que la alimentan.</li><li><strong>Pendiente:</strong> lo que hay que confirmar con la cooperativa o con el proveedor.</li></ul><h3 id="hallazgo-principal" tabindex="-1">Hallazgo principal <a class="header-anchor" href="#hallazgo-principal" aria-label="Permalink to &quot;Hallazgo principal&quot;">​</a></h3><p>Procoop es un producto multi-cooperativa y trae <strong>muchas más integraciones de las que usa una sola cooperativa</strong>. Por ejemplo, la capa de cobranza tiene unos 130 formatos de archivo (bancos, Red Link, SIRO, Banelco, Rapipago, Pago Fácil, tarjetas, QR) y hay 91 formatos de código de barras, uno por cooperativa cliente. En el namespace propio de Laguna Larga (<code>Cobranzas.Entidades.LAG</code>) solo aparece un importador de <strong>Red Link</strong>, y en la DEMO los entes configurados son DOCUMENTOS A COBRAR, RED LINK y SIRO [P].</p><p><strong>Consecuencia:</strong> el primer paso es pedirle a la cooperativa la lista de integraciones que <em>usa hoy</em>, con un archivo de ejemplo anonimizado de cada una. Sin eso, el riesgo es construir conectores que nadie usa o, peor, olvidar uno que se usa todos los días.</p><hr><h2 id="_1-resumen" tabindex="-1">1. Resumen <a class="header-anchor" href="#_1-resumen" aria-label="Permalink to &quot;1. Resumen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Grupo</th><th>Integraciones</th><th>Prioridad</th></tr></thead><tbody><tr><td>Fiscal nacional (ARCA)</td><td>Factura electrónica, padrón de contribuyentes, regímenes informativos, Mis Comprobantes</td><td>A (factura y padrón), B (resto)</td></tr><tr><td>Fiscal provincial</td><td>Rentas Córdoba (IIBB, CVP, SIRCAR), otras provincias</td><td>A</td></tr><tr><td>Cobranza por redes</td><td>Red Link, SIRO, código de barras en la factura</td><td>A</td></tr><tr><td>Pagos digitales</td><td>Pagos360, Mercado Pago, QR interoperable, otros botones</td><td>A (los que use la cooperativa)</td></tr><tr><td>Débito automático</td><td>CBU y tarjetas</td><td>A</td></tr><tr><td>Subsidios y tarifa social</td><td>Padrones de segmentación (Secretaría de Energía / RASE)</td><td>A</td></tr><tr><td>Reguladores</td><td>ERSeP, ENARGAS, ENACOM, Secretaría de Energía</td><td>B</td></tr><tr><td>Federación y terceros</td><td>FECESCOR, rendición de tasas de terceros, EPEC</td><td>B</td></tr><tr><td>Lectura de medidores</td><td>Lectores portátiles, app de lecturas, telemedición</td><td>A o B, según cómo lea la cooperativa</td></tr><tr><td>Medidores prepagos</td><td>Discar, NEXO, CashPower, Boiero y otros</td><td>A si la cooperativa vende prepago</td></tr><tr><td>Bancos y tesorería</td><td>Interbanking, extractos, cotizaciones</td><td>B</td></tr><tr><td>Sueldos</td><td>Libro de Sueldo Digital, SICOSS, SICORE</td><td>B</td></tr><tr><td>Comunicaciones</td><td>E-mail, WhatsApp, SMS, IVR</td><td>B</td></tr><tr><td>Portal, app y API</td><td>Portal del socio, app de campo, API para terceros</td><td>B</td></tr><tr><td>Firma digital</td><td>Recibos de sueldo, planes de pago</td><td>C</td></tr><tr><td>GIS y mapas</td><td>Exportación GIS, KML, parcelas</td><td>C</td></tr><tr><td>Servicios TIC</td><td>Centrales telefónicas, MikroTik, Wispro, Radius, OLT</td><td>C (solo si presta el servicio)</td></tr><tr><td>Análisis y contabilidad externa</td><td>Power BI, sistema contable externo</td><td>C</td></tr><tr><td>Hardware local</td><td>Lectores de tarjeta, lector de billetes, impresoras de ticket, turnero</td><td>C</td></tr><tr><td>Migración</td><td>Base SQL Server de Procoop, DBF, Excel</td><td>A (una sola vez)</td></tr></tbody></table><hr><h2 id="_2-fiscal-nacional-arca" tabindex="-1">2. Fiscal nacional (ARCA) <a class="header-anchor" href="#_2-fiscal-nacional-arca" aria-label="Permalink to &quot;2. Fiscal nacional (ARCA)&quot;">​</a></h2><h3 id="_2-1-factura-electronica-—-wsaa-wsfev1" tabindex="-1">2.1 Factura electrónica — WSAA + WSFEv1 <a class="header-anchor" href="#_2-1-factura-electronica-—-wsaa-wsfev1" aria-label="Permalink to &quot;2.1 Factura electrónica — WSAA + WSFEv1&quot;">​</a></h3><ul><li><strong>Prioridad:</strong> A. Etapa 1.</li><li><strong>Dirección:</strong> saliente, con respuesta inmediata.</li><li><strong>Medio:</strong> servicio web SOAP sobre HTTPS. La autenticación se hace contra WSAA con un certificado X.509 de la cooperativa; WSAA devuelve un ticket de acceso que dura 12 horas.</li><li><strong>Operaciones que usa Procoop</strong> [B] (<code>WSFEV1.Service</code>): <code>FECAESolicitar</code>, <code>FECompUltimoAutorizado</code>, <code>FECompConsultar</code>, <code>FECAEASolicitar</code>, <code>FECAEARegInformativo</code>, <code>FECAEASinMovimientoInformar</code>, y los <code>FEParamGet*</code> (tipos de comprobante, IVA, tributos, puntos de venta, condición IVA del receptor, actividades, cotizaciones).</li><li><strong>Modalidades:</strong> CAE (autorización comprobante por comprobante) y CAEA (código anticipado por quincena, informado después). También CESP [M][T] <code>CESPAFIP</code>.</li><li><strong>Frecuencia:</strong> en cada emisión. La facturación masiva genera unos 12.500 comprobantes por mes [P]; el CAEA se pide por quincena.</li><li><strong>Evidencia:</strong> [P] alerta &quot;Hay facturas electrónicas pendientes de autorizar!&quot;; [T] <code>ELECTRONICA_FC</code>, <code>ELECTRONICA_IVA</code>, <code>ELECTRONICA_TRIB</code>, <code>ELECTRONICA_RELCOMP</code>, <code>EMPAFIP</code>; [B] <code>clsFacturacionElectronica</code> (<code>AutorizaFacturas</code>, <code>AutorizaFacturasCAEA</code>, <code>ConsultarCAE</code>, <code>InformarCAEA</code>, <code>ConsultarInconsistencias</code>).</li><li><strong>Depende de:</strong> Facturación (9), Titulares (3, condición IVA y documento), Tablas fiscales (2).</li><li><strong>Diseño propuesto:</strong> cola de autorización con reintentos. Antes de cada lote se consulta <code>FECompUltimoAutorizado</code> para no duplicar números si un envío anterior quedó a medias. Tablero de pendientes y rechazados con el motivo devuelto por ARCA. Ambientes de homologación y producción separados.</li><li><strong>Pendiente:</strong> si la masiva usa CAE o CAEA; puntos de venta habilitados (se vieron 0022, 0028 y 0097 [P]); quién custodia el certificado y cuándo vence.</li></ul><h3 id="_2-2-padron-de-contribuyentes-—-a13-y-constancia" tabindex="-1">2.2 Padrón de contribuyentes — A13 y constancia <a class="header-anchor" href="#_2-2-padron-de-contribuyentes-—-a13-y-constancia" aria-label="Permalink to &quot;2.2 Padrón de contribuyentes — A13 y constancia&quot;">​</a></h3><ul><li><strong>Prioridad:</strong> A.</li><li><strong>Dirección:</strong> saliente, consulta.</li><li><strong>Medio:</strong> servicio web SOAP con el mismo ticket de WSAA.</li><li><strong>Evidencia:</strong> [B] <code>WSPA13.PersonaServiceA13</code> (<code>getPersona</code>, <code>getIdPersonaListByDocumento</code>) y <code>WSPN3.ContribuyenteNivel3SelectServiceImplService</code>; [B] <code>Impuestos.busca_cuit_afip</code>, <code>ValidaCuit</code>, <code>GetDatosContribuyente</code>.</li><li><strong>Uso:</strong> completar razón social, domicilio fiscal y condición frente al IVA al dar de alta un titular o un proveedor, y obtener el CUIT a partir del DNI.</li><li><strong>Frecuencia:</strong> a demanda, en altas y modificaciones; opcionalmente una revalidación masiva periódica.</li><li><strong>Depende de:</strong> Titulares (3), Compras (16).</li></ul><h3 id="_2-3-regimenes-informativos-y-libros-digitales" tabindex="-1">2.3 Regímenes informativos y libros digitales <a class="header-anchor" href="#_2-3-regimenes-informativos-y-libros-digitales" aria-label="Permalink to &quot;2.3 Regímenes informativos y libros digitales&quot;">​</a></h3><ul><li><strong>Prioridad:</strong> B. Se pueden seguir generando desde Procoop mientras dure el paralelo.</li><li><strong>Dirección:</strong> saliente.</li><li><strong>Medio:</strong> archivos TXT de ancho fijo que se suben al sitio de ARCA (no hay servicio web).</li><li><strong>Evidencia</strong> [B] <code>Facturacion.Archivos</code>: <ul><li><code>RG3685</code> y <code>RG3685_ITEMS</code>: régimen de información de compras y ventas (CITI).</li><li><code>RG1361</code>, <code>RG3349</code>, <code>RG3571</code>, <code>CIR7021</code>: otros regímenes informativos.</li><li><code>PercepcionSICORE</code>: retenciones y percepciones de ventas, proveedores y sueldos.</li><li><code>clsSIRE</code>: formularios F2004 y F2005.</li><li><code>RetencionesMunicipales.Exportar_SeguridadSocialArca</code>.</li></ul></li><li><strong>Frecuencia:</strong> mensual, según el vencimiento de cada régimen.</li><li><strong>Depende de:</strong> Facturación (9), Compras (16), Sueldos (20), Contabilidad (19).</li><li><strong>Pendiente:</strong> cuáles presenta hoy la cooperativa.</li></ul><h3 id="_2-4-mis-comprobantes-importacion" tabindex="-1">2.4 Mis Comprobantes (importación) <a class="header-anchor" href="#_2-4-mis-comprobantes-importacion" aria-label="Permalink to &quot;2.4 Mis Comprobantes (importación)&quot;">​</a></h3><ul><li><strong>Prioridad:</strong> B.</li><li><strong>Dirección:</strong> entrante.</li><li><strong>Medio:</strong> archivo CSV o Excel descargado de ARCA.</li><li><strong>Evidencia:</strong> [B] <code>clsLibroIVAdigital.Importar_ComprobantesAfip</code>, <code>Comparar_LibroCompras</code>, <code>Comparar_LibroVenta</code>, <code>Get_Informe_ComprobantesNoProcoop</code>.</li><li><strong>Uso:</strong> cargar los comprobantes recibidos de proveedores y cruzar los libros de IVA con lo que ARCA tiene registrado.</li><li><strong>Frecuencia:</strong> mensual.</li><li><strong>Depende de:</strong> Compras (16), Contabilidad (19).</li></ul><hr><h2 id="_3-fiscal-provincial" tabindex="-1">3. Fiscal provincial <a class="header-anchor" href="#_3-fiscal-provincial" aria-label="Permalink to &quot;3. Fiscal provincial&quot;">​</a></h2><h3 id="_3-1-rentas-cordoba-—-ingresos-brutos-cvp-y-sircar" tabindex="-1">3.1 Rentas Córdoba — Ingresos Brutos, CVP y SIRCAR <a class="header-anchor" href="#_3-1-rentas-cordoba-—-ingresos-brutos-cvp-y-sircar" aria-label="Permalink to &quot;3.1 Rentas Córdoba — Ingresos Brutos, CVP y SIRCAR&quot;">​</a></h3><ul><li><strong>Prioridad:</strong> A. Las percepciones forman parte del importe de la factura, así que sin esto no coinciden las facturas en el paralelo.</li><li><strong>Dirección:</strong> entrante (padrones) y saliente (declaraciones).</li><li><strong>Medio:</strong> archivos.</li><li><strong>Evidencia:</strong><ul><li>[M][T] Código de Validación Provincial (CVP): <code>CVPIIBB</code>, relacionado con <code>COMPROB</code> y <code>PTOVENTA</code>; [B] <code>clsFacturasImpresion.Get_CVP</code>.</li><li>[T] <code>IIBB_LUA</code>; [B] <code>clsCuentas.GetCondicionIIBB_LUA</code>, <code>GetDatosIbBb_Lua</code>, <code>RegistrarIi_BB</code>; validación <code>clsFacturacionMasiva.ValidarLUA</code>.</li><li>[B] <code>SIRCAR.Exportar_ArchivoPercepciones</code> y <code>Exportar_ArchivoRetenciones</code> (SIRCAR es el sistema de agentes de recaudación de Convenio Multilateral).</li></ul></li><li><strong>Frecuencia:</strong> padrón mensual (entrante); declaración de percepciones y retenciones mensual o quincenal (saliente).</li><li><strong>Depende de:</strong> Titulares (3), Facturación (9), Compras (16).</li><li><strong>Pendiente:</strong> qué significa exactamente LUA en este contexto; formato del padrón vigente; si el CVP se imprime en la factura.</li></ul><h3 id="_3-2-otras-provincias" tabindex="-1">3.2 Otras provincias <a class="header-anchor" href="#_3-2-otras-provincias" aria-label="Permalink to &quot;3.2 Otras provincias&quot;">​</a></h3><ul><li><strong>Prioridad:</strong> C para Laguna Larga.</li><li><strong>Evidencia:</strong> [B] <code>ImportarIIBB_BsAs</code>, <code>ImportarIIBB_RN_012017</code>, <code>Exportar_IngresosBrutosArba</code>, <code>Exportar_IngresosBrutosLaPampa</code>, <code>Exportar_IngresosBrutosSantaFe</code>, <code>Get_RetencionesIIBB_RioNegro</code>.</li><li><strong>Nota:</strong> solo importan si el producto se ofrece a cooperativas de otras provincias. Conviene diseñar el motor de padrones y percepciones para que cada jurisdicción sea una configuración y no un desarrollo.</li></ul><hr><h2 id="_4-cobranza-por-redes" tabindex="-1">4. Cobranza por redes <a class="header-anchor" href="#_4-cobranza-por-redes" aria-label="Permalink to &quot;4. Cobranza por redes&quot;">​</a></h2><p>Todas las redes funcionan igual: el sistema <strong>publica la deuda</strong> (archivo o servicio), el socio paga en la red y la red <strong>devuelve la rendición</strong> con los pagos. Procoop lo implementa con dos clases base, <code>Exportador_Base</code> e <code>Importador_Base</code> [B], que validan duplicados, importes, comprobantes anulados o bloqueados y titulares notificados.</p><h3 id="_4-1-red-link" tabindex="-1">4.1 Red Link <a class="header-anchor" href="#_4-1-red-link" aria-label="Permalink to &quot;4.1 Red Link&quot;">​</a></h3><ul><li><strong>Prioridad:</strong> A. Configurado en la DEMO [P] y con importador propio de Laguna Larga [B] <code>Cobranzas.Entidades.LAG.Red_Link</code>.</li><li><strong>Dirección:</strong> bidireccional.</li><li><strong>Medio:</strong> archivos de ancho fijo. Procoop tiene más de 20 variantes de formato (<code>E_RedLink_19_7</code>, <code>E_RedLink_19_10</code>, <code>E_RedLink_Continuo</code>, <code>E_RedLink_Lotes</code>, etc.) y cada exportación genera además un archivo de control (<code>Exportar_Control</code>).</li><li><strong>Frecuencia:</strong> archivo de deuda después de cada facturación, y actualizaciones diarias en la modalidad &quot;continua&quot;; rendición diaria.</li><li><strong>Evidencia:</strong> [T] <code>RED_LINK</code>, <code>DEUDARED</code>, <code>DEUDARED_TIPO</code>, <code>RECHAZOS</code>.</li><li><strong>Depende de:</strong> Facturación (9), Cuenta corriente (10), Cobranza (11), Mora (12, reconexión por pago).</li><li><strong>Pendiente:</strong> qué variante de formato usa Laguna Larga; código de ente; si la entrega es por SFTP o por carga manual; un archivo de deuda y uno de rendición de ejemplo.</li></ul><h3 id="_4-2-siro-banco-roela" tabindex="-1">4.2 SIRO (Banco Roela) <a class="header-anchor" href="#_4-2-siro-banco-roela" aria-label="Permalink to &quot;4.2 SIRO (Banco Roela)&quot;">​</a></h3><ul><li><strong>Prioridad:</strong> A. Configurado en la DEMO [P].</li><li><strong>Dirección:</strong> bidireccional.</li><li><strong>Medio:</strong> archivos (base de deuda y rendición) y también API, con QR estático y dinámico.</li><li><strong>Evidencia:</strong> [T] <code>SIRO_BASEDEUDA</code>; [B] <code>clsSIRO</code> (<code>InformarBase</code>, <code>ActualizarBaseDeuda</code>, <code>ObtenerPagos_APISIRO</code>, <code>Importar_PagosAPI</code>, <code>GenerarQrDinamico</code>, <code>GenerarQRCaja</code>); importadores <code>SIRO</code>, <code>SIRO_Extendido</code>, <code>Siro_Integrado</code>, <code>Siro_Unificado</code>.</li><li><strong>Frecuencia:</strong> base de deuda después de cada facturación; pagos por consulta periódica a la API (Procoop usa un temporizador) o rendición diaria.</li><li><strong>Depende de:</strong> los mismos módulos que Red Link.</li><li><strong>Pendiente:</strong> si Laguna Larga usa archivo, API o ambos; credenciales de la API.</li></ul><h3 id="_4-3-codigo-de-barras-de-la-factura" tabindex="-1">4.3 Código de barras de la factura <a class="header-anchor" href="#_4-3-codigo-de-barras-de-la-factura" aria-label="Permalink to &quot;4.3 Código de barras de la factura&quot;">​</a></h3><ul><li><strong>Prioridad:</strong> A. Sin el código correcto, las redes no pueden cobrar la factura.</li><li><strong>Dirección:</strong> no es un intercambio sino un formato que imponen las redes; se imprime en la factura.</li><li><strong>Evidencia:</strong> [B] <code>Facturacion.CodigoBarra.Clientes</code> (91 formatos, uno por cooperativa), <code>CodigoBarra.Genericos</code> (Banco de Córdoba de 43 a 56 dígitos, Pago Fácil, Credicoop, Banco Nación, formato AFIP) y <code>Codigo_Base</code> con 9 algoritmos de dígito verificador.</li><li><strong>Depende de:</strong> Facturación (9), impresión de la factura.</li><li><strong>Pendiente:</strong> cuál es el formato de Laguna Larga. La forma más segura de validarlo en el paralelo es comparar el código generado por ambos sistemas para la misma factura.</li></ul><h3 id="_4-4-otras-redes-y-entes-recaudadores" tabindex="-1">4.4 Otras redes y entes recaudadores <a class="header-anchor" href="#_4-4-otras-redes-y-entes-recaudadores" aria-label="Permalink to &quot;4.4 Otras redes y entes recaudadores&quot;">​</a></h3><ul><li><strong>Prioridad:</strong> C, salvo que la cooperativa confirme que los usa.</li><li><strong>Evidencia:</strong> [B] Banelco/PMC (más de 15 variantes), Rapipago, Pago Fácil, CobroExpress, ProvinciaNet, Fiserv, PampaPagos, y bancos (Córdoba, Nación, Provincia, Macro, Comafi, Supervielle, Credicoop, Chubut).</li><li><strong>Diseño propuesto:</strong> un único motor de conectores donde cada ente se define por configuración (estructura de registros, campos, dígito verificador). Así, sumar una red no requiere un desarrollo nuevo.</li></ul><hr><h2 id="_5-pagos-digitales" tabindex="-1">5. Pagos digitales <a class="header-anchor" href="#_5-pagos-digitales" aria-label="Permalink to &quot;5. Pagos digitales&quot;">​</a></h2><h3 id="_5-1-pagos360" tabindex="-1">5.1 Pagos360 <a class="header-anchor" href="#_5-1-pagos360" aria-label="Permalink to &quot;5.1 Pagos360&quot;">​</a></h3><ul><li><strong>Prioridad:</strong> A, según el alcance.</li><li><strong>Dirección:</strong> bidireccional.</li><li><strong>Medio:</strong> API REST. Procoop consulta periódicamente los pagos (<code>InicializarTimer</code>, <code>Importar_PagosAPI</code>) en lugar de recibir notificaciones.</li><li><strong>Funciones</strong> [B] <code>clsPagos360</code>: solicitudes de pago, QR estático y dinámico, QR para la caja, débito automático por CBU y por tarjeta (<code>Registrar_DebitoCbu</code>, <code>Registrar_DebitoTarjeta</code>, <code>Actualizar_EstadosDebitos</code>), reversiones con comisión, pagos rechazados.</li><li><strong>Evidencia:</strong> [T] <code>PAGOS360</code>, <code>PAGOS360_ITEMS</code>, <code>PAGOS360_PAGOS</code>, <code>PAGOS360_EXTRAS</code>; <code>FACTURAS</code> se relaciona con <code>PAGOS360_ITEMS</code>.</li><li><strong>Frecuencia:</strong> en tiempo real (creación de la solicitud) y conciliación periódica.</li><li><strong>Depende de:</strong> Facturación (9), Cuenta corriente (10), Cobranza (11), Portal (27), WhatsApp (link de pago).</li><li><strong>Diseño propuesto:</strong> recibir las notificaciones del proveedor (webhooks) y conciliar una vez por día como respaldo.</li></ul><h3 id="_5-2-mercado-pago-macro-y-otros-botones" tabindex="-1">5.2 Mercado Pago, Macro y otros botones <a class="header-anchor" href="#_5-2-mercado-pago-macro-y-otros-botones" aria-label="Permalink to &quot;5.2 Mercado Pago, Macro y otros botones&quot;">​</a></h3><ul><li><strong>Prioridad:</strong> C hasta que la cooperativa confirme cuáles usa.</li><li><strong>Evidencia:</strong> [B] <code>MercadoPago.dll</code> y <code>clsMercadoPago</code>; <code>PlusPagosSecurityKitNetFramework.dll</code> y <code>clsMacro</code> (botón de pago Macro); <code>clsNaranjaX</code>, <code>clsHelipagos</code>, <code>clsPagostic</code>, <code>clsPayFun</code>, <code>clsProntoPago</code>, <code>clsProvinciaNet</code> (lotes de QR), <code>clsSiPago</code>.</li><li><strong>Nota:</strong> todos comparten la misma interfaz en Procoop (<code>Registrar_Solicitudes</code>, <code>Obtener_Pago</code>, <code>GetInforme_ComprobantePagarRecargos</code>). En el sistema nuevo conviene una interfaz única de &quot;pasarela de pago&quot; con un adaptador por proveedor.</li></ul><hr><h2 id="_6-debito-automatico" tabindex="-1">6. Débito automático <a class="header-anchor" href="#_6-debito-automatico" aria-label="Permalink to &quot;6. Débito automático&quot;">​</a></h2><ul><li><strong>Prioridad:</strong> A.</li><li><strong>Dirección:</strong> bidireccional. Se envía el archivo de débitos y se recibe el de novedades y rechazos.</li><li><strong>Medio:</strong> archivos por banco o por tarjeta.</li><li><strong>Evidencia:</strong> [P] Importar y Exportar archivos de débitos automáticos, Importar Archivo de Novedades; [T] <code>DEBITO_EXCLUSION</code>, <code>ADHSOC</code> (adhesiones), carpeta <code>Debitos</code>; [B] <code>DebitoDirecto</code>, <code>DebitoMacro</code>, <code>BancoNacion_4</code>, <code>E_Visa_Debito</code>, <code>VisaCredito</code>, <code>MasterCard_Debitos</code>, <code>TarjetaNaranja</code>, <code>clsEntidadesRecaudadoras.Archivo_Novedades_Visa</code>.</li><li><strong>Frecuencia:</strong> mensual, alineada con los vencimientos de la factura.</li><li><strong>Depende de:</strong> Titulares (adhesiones, CBU), Facturación (9), Cuenta corriente (10), Mora (12, los rechazos vuelven a deuda).</li><li><strong>Pendiente:</strong> qué bancos y tarjetas tiene adheridos la cooperativa y cuántos socios hay en cada uno.</li></ul><hr><h2 id="_7-subsidios-y-tarifa-social" tabindex="-1">7. Subsidios y tarifa social <a class="header-anchor" href="#_7-subsidios-y-tarifa-social" aria-label="Permalink to &quot;7. Subsidios y tarifa social&quot;">​</a></h2><ul><li><strong>Prioridad:</strong> A. La categoría de subsidio cambia el precio de la energía y del gas, así que sin el padrón actualizado las facturas no coinciden en el paralelo. No figura en la sección 30 del alcance.</li><li><strong>Dirección:</strong> entrante (padrones de beneficiarios) y saliente (rendición de lo bonificado).</li><li><strong>Medio:</strong> archivos Excel o TXT publicados por la autoridad.</li><li><strong>Evidencia:</strong> [B] <code>clsSegmentacion</code> (<code>Importar_Energia_RASE</code>, <code>Importar_Energia_RASE_NIS</code>, <code>ImportarEnergia_493_25</code>, <code>ImportarGas_SEF</code>, <code>Importar_ZonaFria</code>, <code>Recategorizar</code>); <code>clsTarifaSocial</code> (<code>Export_ERSEP166</code>, <code>Export_ERSEP296</code>, <code>Export_ERSEP617</code>, <code>Export_GasNatural</code>); <code>clsCirculares.Exportar_Archivo_RASE</code>, <code>GenerarArchivoCompensacionSubsidio</code>; carpetas <code>Segmentacion</code> y <code>tarifasocial</code> en el servidor.</li><li><strong>Frecuencia:</strong> cada vez que la autoridad publica un padrón (típicamente mensual) y antes de cada facturación.</li><li><strong>Depende de:</strong> Servicios y categorías (4), Tarifas (7), Facturación (9).</li><li><strong>Pendiente:</strong> formato y canal del padrón vigente para energía y para gas; normativa nacional y provincial aplicable hoy.</li></ul><hr><h2 id="_8-reguladores" tabindex="-1">8. Reguladores <a class="header-anchor" href="#_8-reguladores" aria-label="Permalink to &quot;8. Reguladores&quot;">​</a></h2><h3 id="_8-1-ersep-ente-regulador-de-servicios-publicos-de-cordoba" tabindex="-1">8.1 ERSeP (Ente Regulador de Servicios Públicos de Córdoba) <a class="header-anchor" href="#_8-1-ersep-ente-regulador-de-servicios-publicos-de-cordoba" aria-label="Permalink to &quot;8.1 ERSeP (Ente Regulador de Servicios Públicos de Córdoba)&quot;">​</a></h3><ul><li><strong>Prioridad:</strong> B. No figura en la sección 30 del alcance, pero aplica a Laguna Larga por estar en Córdoba.</li><li><strong>Dirección:</strong> saliente.</li><li><strong>Medio:</strong> archivos Excel o TXT.</li><li><strong>Evidencia:</strong> [B] <code>clsInformes_Consumos.Exportar_Archivo_ERSep</code>, <code>clsCirculares.Exportar_Excel_ERSeP_DNUN_311_2020</code>, <code>clsInformes_Titulares.ExportarERSEP</code>.</li><li><strong>Frecuencia:</strong> según cada resolución, en general mensual o semestral.</li></ul><h3 id="_8-2-enargas" tabindex="-1">8.2 ENARGAS <a class="header-anchor" href="#_8-2-enargas" aria-label="Permalink to &quot;8.2 ENARGAS&quot;">​</a></h3><ul><li><strong>Prioridad:</strong> B. Laguna Larga tiene servicio de gas natural [P].</li><li><strong>Dirección:</strong> saliente.</li><li><strong>Medio:</strong> paquete de archivos TXT con nombres fijos (usuarios, facturación, conceptos, consumos, morosidad).</li><li><strong>Evidencia:</strong> [M][T] <code>ENGAS_CANTMESES</code>, carpeta <code>ENARGAS</code>; [B] <code>clsEnargas</code> y <code>clsEnargas2</code> (<code>Get_File_USR</code>, <code>Get_File_FDC</code>, <code>Get_File_FDD</code>, <code>Get_File_CMD</code>, <code>Get_File_SICC</code>, <code>ExportExcelMorosidad</code>).</li><li><strong>Frecuencia:</strong> periódica, según el régimen informativo del ENARGAS.</li></ul><h3 id="_8-3-enacom" tabindex="-1">8.3 ENACOM <a class="header-anchor" href="#_8-3-enacom" aria-label="Permalink to &quot;8.3 ENACOM&quot;">​</a></h3><ul><li><strong>Prioridad:</strong> C, solo si la cooperativa presta servicios TIC.</li><li><strong>Evidencia:</strong> [M] Configuración de Conceptos para informe ENACOM; [B] <code>ConfiguracionEnacom.Exportar_Excel_ENACOM_DNU_RES_367_2020</code>, <code>clsEnacom.CargarArchivo</code>.</li></ul><h3 id="_8-4-secretaria-de-energia" tabindex="-1">8.4 Secretaría de Energía <a class="header-anchor" href="#_8-4-secretaria-de-energia" aria-label="Permalink to &quot;8.4 Secretaría de Energía&quot;">​</a></h3><ul><li><strong>Prioridad:</strong> B.</li><li><strong>Evidencia:</strong> [B] <code>clsInformes_Consumos.Get_InformeSecretariaEnergia</code>, <code>CompletarInfoUsuariosGeneradores544</code> (usuarios generadores, energía inyectada).</li><li><strong>Pendiente:</strong> qué informes presenta hoy la cooperativa.</li></ul><hr><h2 id="_9-federacion-y-terceros" tabindex="-1">9. Federación y terceros <a class="header-anchor" href="#_9-federacion-y-terceros" aria-label="Permalink to &quot;9. Federación y terceros&quot;">​</a></h2><h3 id="_9-1-fecescor" tabindex="-1">9.1 FECESCOR <a class="header-anchor" href="#_9-1-fecescor" aria-label="Permalink to &quot;9.1 FECESCOR&quot;">​</a></h3><ul><li><strong>Prioridad:</strong> B.</li><li><strong>Dirección:</strong> saliente.</li><li><strong>Medio:</strong> archivos de rendición.</li><li><strong>Evidencia:</strong> [B] <code>GetDatosInforme.GenerarArchivosRendicion_FECESCOR</code>, <code>clsWEB.ConfigurarFECESCOR</code>, <code>clsInformes_Titulares.ExportarFECESCOR</code>.</li><li><strong>Pendiente:</strong> qué se rinde (fondos, tasas, datos de usuarios) y con qué frecuencia. Confirmar si Laguna Larga está adherida.</li></ul><h3 id="_9-2-rendicion-de-tasas-de-terceros" tabindex="-1">9.2 Rendición de tasas de terceros <a class="header-anchor" href="#_9-2-rendicion-de-tasas-de-terceros" aria-label="Permalink to &quot;9.2 Rendición de tasas de terceros&quot;">​</a></h3><ul><li><strong>Prioridad:</strong> B. La factura incluye tasas municipales y provinciales (alumbrado público, tasas por decreto) [P]; lo cobrado se rinde a cada organismo.</li><li><strong>Dirección:</strong> saliente, y entrante cuando el organismo envía el padrón de lo que hay que facturar.</li><li><strong>Evidencia:</strong> [T] <code>FACTURAS_TERCEROS</code>; [B] <code>clsFacturacionCuotasTerceros</code> (<code>Importar_AlumbradoPublico</code>, <code>ImportarFacturasGAS</code>), <code>clsTerceros</code>, <code>clsFacturas_DatosExtras.CargarFacturasTerceros</code>.</li><li><strong>Pendiente:</strong> lista de organismos y el formato de cada rendición.</li></ul><h3 id="_9-3-epec" tabindex="-1">9.3 EPEC <a class="header-anchor" href="#_9-3-epec" aria-label="Permalink to &quot;9.3 EPEC&quot;">​</a></h3><ul><li><strong>Prioridad:</strong> B.</li><li><strong>Uso:</strong> la cooperativa compra la energía a EPEC; la integración serviría para cargar la factura de compra y calcular las pérdidas (energía comprada contra energía vendida).</li><li><strong>Evidencia:</strong> solo [T] <code>FACT_EPEC</code>. No se encontró lógica en <code>ReglasNegocio.dll</code>, por lo que puede ser una carga manual o una tabla en desuso.</li><li><strong>Pendiente:</strong> confirmar si se usa y cómo llega la información (PDF, archivo o portal).</li></ul><hr><h2 id="_10-lectura-de-medidores" tabindex="-1">10. Lectura de medidores <a class="header-anchor" href="#_10-lectura-de-medidores" aria-label="Permalink to &quot;10. Lectura de medidores&quot;">​</a></h2><h3 id="_10-1-lectores-portatiles-y-app-de-lecturas" tabindex="-1">10.1 Lectores portátiles y app de lecturas <a class="header-anchor" href="#_10-1-lectores-portatiles-y-app-de-lecturas" aria-label="Permalink to &quot;10.1 Lectores portátiles y app de lecturas&quot;">​</a></h3><ul><li><strong>Prioridad:</strong> A si Laguna Larga lee con dispositivos o con la app; B si las lecturas se cargan a mano. Sin lecturas no hay facturación.</li><li><strong>Dirección:</strong> bidireccional. Se envía la ruta de lectura y se recibe el estado de cada medidor.</li><li><strong>Medio:</strong><ul><li>Dispositivos conectados a la PC (protocolo de dispositivos portátiles de Windows), con archivos de ruta. [B] <code>clsWindowsDevice</code>, <code>clsTelemed.Archivo_ExportarPSION</code>, <code>Archivo_ImportacionPSION</code>.</li><li>App móvil propia que sincroniza con una base MySQL en la nube y sube fotos a Amazon S3. [B] <code>clsPMovil_Telemed</code> (<code>GetImgLecturas</code>, <code>EliminarImagenesS3</code>), <code>clsPMovil.EnviarRutaACaptor</code>, <code>RecibirDatosCaptor</code>.</li><li>Excel y CSV. [B] <code>clsTelemed.Archivo_ImportarExcel</code>, <code>clsDetalleRuta.ParsearLineasCSV</code>.</li></ul></li><li><strong>Frecuencia:</strong> mensual por ruta de lectura (zona, sector y recorrido).</li><li><strong>Depende de:</strong> Medidores (5), Lecturas y consumos (6), Facturación (9).</li><li><strong>Diseño propuesto:</strong> app de lecturas propia, que funcione sin conexión, con foto, coordenadas y validación de consumo fuera de rango en el momento.</li></ul><h3 id="_10-2-telemedicion-ami-mdm" tabindex="-1">10.2 Telemedición (AMI/MDM) <a class="header-anchor" href="#_10-2-telemedicion-ami-mdm" aria-label="Permalink to &quot;10.2 Telemedición (AMI/MDM)&quot;">​</a></h3><ul><li><strong>Prioridad:</strong> B.</li><li><strong>Dirección:</strong> entrante (lecturas) y saliente (comandos de corte y reconexión).</li><li><strong>Medio:</strong> varía por fabricante: REST, SOAP, TCP o acceso directo a la base del proveedor.</li><li><strong>Evidencia:</strong> [M][T] <code>TELEMEDICION</code>, <code>TELEMED_COMM</code>, <code>AUDITORIA_TELEMEDICION</code>; [B] <code>Varios.Telemed.Telemedicion</code>, con conectores para QUO, Kaptor, Silexis, Hexing, Discar y otros. Cada conector expone la misma interfaz: <code>TomaEstado</code>, <code>CorteServicio</code>, <code>ReconexionServicio</code>, <code>AsignacionMedidor</code>, <code>RetiroMedidor</code>, <code>CambioCategoria</code>.</li><li><strong>Pendiente:</strong> si Laguna Larga tiene medidores telemedidos y de qué marca.</li></ul><h3 id="_10-3-medidores-prepagos" tabindex="-1">10.3 Medidores prepagos <a class="header-anchor" href="#_10-3-medidores-prepagos" aria-label="Permalink to &quot;10.3 Medidores prepagos&quot;">​</a></h3><ul><li><strong>Prioridad:</strong> A si la cooperativa vende energía prepaga [M][T].</li><li><strong>Dirección:</strong> bidireccional. Al cobrar una recarga, el sistema pide el código de crédito al sistema del fabricante; además recibe los consumos.</li><li><strong>Medio:</strong> según el fabricante.</li><li><strong>Evidencia:</strong> [B] <code>CargaCreditoPrepago</code> en los conectores Discar, NEXO (cuatro variantes: TCP, SQL, Plus y base), CashPower, Boiero, C_Token, Silexis y BATCOM; <code>clsPrepaga</code>, <code>clsTelemediciones.RegistroVentaPrepagaTelemed</code>; <code>clsWeb_CoopOnline.AutorizarPrepaga</code> (recarga desde el portal).</li><li><strong>Depende de:</strong> Medidores (5), Prepago, Cobranza (11), Portal (27).</li><li><strong>Pendiente:</strong> marca del sistema prepago de Laguna Larga y si la recarga es online o con token.</li></ul><hr><h2 id="_11-bancos-y-tesoreria" tabindex="-1">11. Bancos y tesorería <a class="header-anchor" href="#_11-bancos-y-tesoreria" aria-label="Permalink to &quot;11. Bancos y tesorería&quot;">​</a></h2><h3 id="_11-1-interbanking" tabindex="-1">11.1 Interbanking <a class="header-anchor" href="#_11-1-interbanking" aria-label="Permalink to &quot;11.1 Interbanking&quot;">​</a></h3><ul><li><strong>Prioridad:</strong> B.</li><li><strong>Dirección:</strong> saliente (archivo de transferencias a proveedores) y entrante (movimientos para conciliar).</li><li><strong>Medio:</strong> archivos.</li><li><strong>Evidencia:</strong> [T] <code>INTERBANKING</code>, <code>MOV_INTERBANKING</code>, <code>SU_AUDIT_TRA_INTERBANKING</code>; [B] <code>clsProveedor.ExportarArchivo_Interbanking</code>, <code>clsInterbanking</code> (<code>getMovimientosCuentaInterbanking</code>, <code>GuardarConciliacion</code>, <code>getSaldosCuentasInterbanking</code>).</li><li><strong>Frecuencia:</strong> diaria o por lote de pagos.</li><li><strong>Depende de:</strong> Compras (16), Tesorería (18), Sueldos (20, pago de haberes).</li></ul><h3 id="_11-2-extractos-bancarios" tabindex="-1">11.2 Extractos bancarios <a class="header-anchor" href="#_11-2-extractos-bancarios" aria-label="Permalink to &quot;11.2 Extractos bancarios&quot;">​</a></h3><ul><li><strong>Prioridad:</strong> B.</li><li><strong>Dirección:</strong> entrante.</li><li><strong>Medio:</strong> archivo del home banking (CSV, Excel o formato del banco).</li><li><strong>Evidencia:</strong> [B] <code>clsConciliacion</code>, <code>clsCuentas.ImportarMovTesore</code>.</li><li><strong>Diseño propuesto:</strong> importación con conciliación asistida, como propone el alcance.</li></ul><h3 id="_11-3-cotizacion-de-monedas" tabindex="-1">11.3 Cotización de monedas <a class="header-anchor" href="#_11-3-cotizacion-de-monedas" aria-label="Permalink to &quot;11.3 Cotización de monedas&quot;">​</a></h3><ul><li><strong>Prioridad:</strong> C.</li><li><strong>Evidencia:</strong> [B] <code>clsTipMon.GetCotizacion</code>; <code>FEParamGetCotizacion</code> de ARCA.</li><li><strong>Nota:</strong> se puede tomar directamente de ARCA.</li></ul><hr><h2 id="_12-sueldos" tabindex="-1">12. Sueldos <a class="header-anchor" href="#_12-sueldos" aria-label="Permalink to &quot;12. Sueldos&quot;">​</a></h2><ul><li><strong>Prioridad:</strong> B.</li><li><strong>Dirección:</strong> saliente (Libro de Sueldo Digital, SICORE) y entrante (importación SICOSS).</li><li><strong>Medio:</strong> archivos TXT para los sistemas de ARCA.</li><li><strong>Evidencia:</strong> [M] Libro sueldo digital (deshabilitado en la DEMO); [B] <code>LibroSueldoDigital</code> (registros tipo 1 a 5), <code>clsSueldos.Importar_Sicoss</code>, <code>clsImportacionArchivos.ImportarSicossDb</code>, <code>PercepcionSICORE.Exportar_Sueldos</code>; <code>clsGanancias</code> (formulario 572).</li><li><strong>Frecuencia:</strong> mensual.</li><li><strong>Pendiente:</strong> si la cooperativa liquida sueldos en Procoop o con un estudio externo. Si es externo, alcanza con importar el asiento contable.</li></ul><hr><h2 id="_13-comunicaciones" tabindex="-1">13. Comunicaciones <a class="header-anchor" href="#_13-comunicaciones" aria-label="Permalink to &quot;13. Comunicaciones&quot;">​</a></h2><h3 id="_13-1-e-mail" tabindex="-1">13.1 E-mail <a class="header-anchor" href="#_13-1-e-mail" aria-label="Permalink to &quot;13.1 E-mail&quot;">​</a></h3><ul><li><strong>Prioridad:</strong> B. Imprescindible si la cooperativa ya envía la factura por mail.</li><li><strong>Dirección:</strong> saliente.</li><li><strong>Medio:</strong> SMTP o Amazon SES.</li><li><strong>Evidencia:</strong> [T] <code>SENDMAIL</code>, <code>PROMAIL</code>, <code>AUDIT_MAIL</code>, <code>MailTemplates</code>; [B] <code>Mails.Manager</code> (<code>EnvioMailAmazon</code>, <code>UsaAmazonSES</code>, <code>EnviarMailsPendientes</code>), <code>AWSSDK.SimpleEmail.dll</code>, <code>MimeKit.dll</code>; exportación a la herramienta de e-mail marketing Doppler (<code>clsGestionMora.ExportarDopler</code>).</li><li><strong>Frecuencia:</strong> en cada emisión masiva y en eventos (avisos de mora, órdenes de trabajo).</li><li><strong>Diseño propuesto:</strong> proveedor transaccional con dominio propio de la cooperativa (SPF, DKIM y DMARC configurados), registro de entrega y rebotes.</li></ul><h3 id="_13-2-whatsapp" tabindex="-1">13.2 WhatsApp <a class="header-anchor" href="#_13-2-whatsapp" aria-label="Permalink to &quot;13.2 WhatsApp&quot;">​</a></h3><ul><li><strong>Prioridad:</strong> B.</li><li><strong>Dirección:</strong> saliente (plantillas) y entrante (bot de autogestión).</li><li><strong>Medio:</strong> API de WhatsApp Business a través del proveedor Trii [B] <code>TriiTemplateRequest</code>, <code>clsServicio_Procoop.EnviarWspTrii</code>.</li><li><strong>Plantillas que ya existen</strong> [B] <code>Telefonia</code>: confirmación de pago, detalle de comprobantes, link de pago, recarga prepaga, generación de orden de trabajo, cambio de medidor.</li><li><strong>Bot:</strong> [B] <code>clsProcoop_Integra_Tecnica.GetCuentasDniBot</code>, <code>GetReclamosBot</code>, <code>GetCuentaCodigoBot</code>.</li><li><strong>Pendiente:</strong> si la cooperativa tiene número de WhatsApp Business verificado y con qué proveedor; plantillas aprobadas por Meta.</li></ul><h3 id="_13-3-sms" tabindex="-1">13.3 SMS <a class="header-anchor" href="#_13-3-sms" aria-label="Permalink to &quot;13.3 SMS&quot;">​</a></h3><ul><li><strong>Prioridad:</strong> C.</li><li><strong>Evidencia:</strong> [M] Administración de SMS; [B] <code>ProMod_SMS.dll</code>, <code>clsMensaje.Get_SMSPendientes</code>, <code>clsPMovil_Sms</code> (envío a través de la app móvil y MySQL), <code>clsProcoop_Integra.EnviarSms</code>.</li><li><strong>Pendiente:</strong> proveedor actual de SMS.</li></ul><h3 id="_13-4-ivr-y-llamadas-automaticas" tabindex="-1">13.4 IVR y llamadas automáticas <a class="header-anchor" href="#_13-4-ivr-y-llamadas-automaticas" aria-label="Permalink to &quot;13.4 IVR y llamadas automáticas&quot;">​</a></h3><ul><li><strong>Prioridad:</strong> C.</li><li><strong>Evidencia:</strong> [B] <code>clsIVR</code> (archivos para TeleAnouncer, Minerva e IVR de logística).</li><li><strong>Uso:</strong> avisos de deuda por llamada automática.</li></ul><hr><h2 id="_14-portal-app-y-api" tabindex="-1">14. Portal, app y API <a class="header-anchor" href="#_14-portal-app-y-api" aria-label="Permalink to &quot;14. Portal, app y API&quot;">​</a></h2><h3 id="_14-1-portal-del-socio-cooponline" tabindex="-1">14.1 Portal del socio (CoopOnline) <a class="header-anchor" href="#_14-1-portal-del-socio-cooponline" aria-label="Permalink to &quot;14.1 Portal del socio (CoopOnline)&quot;">​</a></h3><ul><li><strong>Prioridad:</strong> B. Pasa a A si los socios ya pagan o descargan la factura desde el portal, porque el servicio no se puede cortar durante el paralelo.</li><li><strong>Cómo funciona en Procoop:</strong> el portal no lee la base de Procoop. Un proceso (<code>Agente Procoop.exe</code>) <strong>sincroniza tablas</strong> con una base MySQL externa (facturas, pagos, consumos, cuentas, débitos, novedades, órdenes) y sube los PDF de las facturas. [B] <code>clsWEB.SincronizarFacturas</code>, <code>SincronizarPagos</code>, <code>SincronizarConsumos</code>, <code>SincronizarCuentas</code>, <code>RegistrarPDFFILE</code>; <code>Agente.Clases.clsWeb_CoopOnline</code> (escucha de cobranzas y recargas prepagas).</li><li><strong>Evidencia:</strong> [M] Procoop WEB (Requisitos y Trámites, Archivos en la Web, Operaciones); [P] marca &quot;Alta desde CoopOnline&quot;; [B] <code>Varios.CoopOnline.clsTramitesWEB</code> (trámites y declaraciones juradas de artefactos).</li><li><strong>En el sistema nuevo:</strong> el portal es parte del mismo sistema y lee los mismos datos, así que esta sincronización desaparece. La integración real es la <strong>migración de usuarios del portal</strong> (correos, cuentas vinculadas, adhesiones a factura digital) para que los socios no tengan que registrarse de nuevo.</li></ul><h3 id="_14-2-app-de-campo-tecnica-y-ventas" tabindex="-1">14.2 App de campo (técnica y ventas) <a class="header-anchor" href="#_14-2-app-de-campo-tecnica-y-ventas" aria-label="Permalink to &quot;14.2 App de campo (técnica y ventas)&quot;">​</a></h3><ul><li><strong>Prioridad:</strong> B.</li><li><strong>Cómo funciona en Procoop:</strong> igual que el portal, sincroniza con MySQL. [B] <code>clsPMovil_Tecnica</code> (envío y recepción de órdenes de trabajo), <code>clsPMovil_Venta</code> (presupuestos y ventas), <code>clsProcoop_Integra_Tecnica.ConfirmarOrdenTrabajoPmovil</code>; <code>FireSharp.dll</code> sugiere notificaciones o datos en Firebase.</li><li><strong>En el sistema nuevo:</strong> app propia sobre la API del sistema, sin base intermedia.</li></ul><h3 id="_14-3-api-para-terceros" tabindex="-1">14.3 API para terceros <a class="header-anchor" href="#_14-3-api-para-terceros" aria-label="Permalink to &quot;14.3 API para terceros&quot;">​</a></h3><ul><li><strong>Prioridad:</strong> B.</li><li><strong>Dirección:</strong> entrante (terceros consultan o registran datos).</li><li><strong>Evidencia:</strong> [T] <code>WS_KEYS</code>, <code>WS_USERS</code>, <code>WS_USERS_ACCOUNTS</code>; [B] <code>ProMod_WebService.dll</code>, <code>clsClientes_Externos</code> (<code>RegistrarCuenta</code>, <code>RegistrarPersona</code>, <code>PutCategoria</code>, <code>Consultar_Servicio</code>), <code>clsProcoop_Integra</code> (deuda por cuenta, comprobantes adeudados, canales de pago).</li><li><strong>Pendiente:</strong> qué terceros consumen hoy esta API (municipio, bot, otra cooperativa, sistema de prepago).</li><li><strong>Diseño propuesto:</strong> API REST documentada con OpenAPI, autenticación por cliente (OAuth2 con credenciales de cliente), permisos por cuenta y auditoría de cada llamada.</li></ul><hr><h2 id="_15-firma-digital-y-electronica" tabindex="-1">15. Firma digital y electrónica <a class="header-anchor" href="#_15-firma-digital-y-electronica" aria-label="Permalink to &quot;15. Firma digital y electrónica&quot;">​</a></h2><ul><li><strong>Prioridad:</strong> C.</li><li><strong>Dirección:</strong> bidireccional con un proveedor de firma.</li><li><strong>Medio:</strong> API (envío del documento, consulta del estado, descarga del firmado).</li><li><strong>Evidencia:</strong> [T] <code>FIRMADIGITAL*</code>, <code>FIRMASELECTRONICAS*</code>, <code>PPAGOS_FIRMAS</code>; [B] <code>Varios.Configuraciones.clsFirmaDigital</code> (<code>EnviarParaFirmar</code>, <code>ObtenerEstadoFirma</code>, <code>ObtenerDocumentosFirmados</code>, <code>MarcarRecibosComoFirmados</code>, <code>EnviarSmsFirmados</code>).</li><li><strong>Uso:</strong> recibos de sueldo, planes de pago con firma del titular y de los garantes, órdenes de pago.</li><li><strong>Pendiente:</strong> proveedor de firma actual.</li></ul><hr><h2 id="_16-gis-y-mapas" tabindex="-1">16. GIS y mapas <a class="header-anchor" href="#_16-gis-y-mapas" aria-label="Permalink to &quot;16. GIS y mapas&quot;">​</a></h2><ul><li><strong>Prioridad:</strong> C.</li><li><strong>Dirección:</strong> saliente (exportación al GIS de la cooperativa) y entrante (parcelas del catastro).</li><li><strong>Medio:</strong> archivos con formato propio de cada cooperativa; KML para Google Earth.</li><li><strong>Evidencia:</strong> [B] <code>Varios.GIS</code> (un exportador por cooperativa: <code>ExportarUsuarios</code>, <code>ExportarConsumos</code>, <code>ExportarAltasBajas</code>); <code>Varios.Generales.GIS</code> (<code>Import_Parcelas</code>, <code>Show_Map</code>); <code>Varios.GoogleEarth</code> y <code>SharpKml.Core.dll</code>; mapas KML de rutas de lectura y de órdenes de trabajo.</li><li><strong>Pendiente:</strong> si Laguna Larga tiene un GIS propio (por ejemplo QGIS) y qué datos le pasa.</li></ul><hr><h2 id="_17-servicios-tic-telefonia-internet-tv" tabindex="-1">17. Servicios TIC (telefonía, internet, TV) <a class="header-anchor" href="#_17-servicios-tic-telefonia-internet-tv" aria-label="Permalink to &quot;17. Servicios TIC (telefonía, internet, TV)&quot;">​</a></h2><ul><li><strong>Prioridad:</strong> C. Solo aplica si la cooperativa presta estos servicios; el alcance ya marca telefonía como un módulo a validar.</li><li><strong>Evidencia:</strong><ul><li>Telefonía fija: [B] <code>Telefonia.clsImportacion</code> importa los registros de llamadas (CDR) de más de 20 modelos de central (Alcatel, Huawei, Iskratel, Broadsoft, Lucent, NEC, entre otros) para tasarlas.</li><li>Telefonía móvil: [B] <code>clsTelefoniaMovil.Importar_ArchivoClaro</code>, <code>Importar_ArchivoPersonal</code>.</li><li>Internet: [B] conectores MikroTik, Wispro, Radius, Radius_Gretix, SmartOlt e Ispfull para alta, corte, reconexión y cambio de plan; [T] <code>MIKROTIK</code>.</li><li>TV u otros: [B] <code>Sensa</code>, <code>Sopnet</code>, <code>clsSitsa</code> (altas, bajas, contratos y corte).</li></ul></li><li><strong>Diseño propuesto:</strong> la misma interfaz de &quot;sistema externo de aprovisionamiento&quot; que la telemedición (alta, corte, reconexión, cambio de categoría), con un adaptador por proveedor.</li></ul><hr><h2 id="_18-analisis-y-contabilidad-externa" tabindex="-1">18. Análisis y contabilidad externa <a class="header-anchor" href="#_18-analisis-y-contabilidad-externa" aria-label="Permalink to &quot;18. Análisis y contabilidad externa&quot;">​</a></h2><h3 id="_18-1-power-bi-y-herramientas-de-analisis" tabindex="-1">18.1 Power BI y herramientas de análisis <a class="header-anchor" href="#_18-1-power-bi-y-herramientas-de-analisis" aria-label="Permalink to &quot;18.1 Power BI y herramientas de análisis&quot;">​</a></h3><ul><li><strong>Prioridad:</strong> C.</li><li><strong>Evidencia:</strong> [T] <code>TABLAS_POWERBI</code> → <code>PERFILES_TABLAS</code>.</li><li><strong>Diseño propuesto:</strong> API de datos de solo lectura o réplica para BI, como propone el alcance.</li></ul><h3 id="_18-2-sistema-contable-externo" tabindex="-1">18.2 Sistema contable externo <a class="header-anchor" href="#_18-2-sistema-contable-externo" aria-label="Permalink to &quot;18.2 Sistema contable externo&quot;">​</a></h3><ul><li><strong>Prioridad:</strong> C. Sube a B si la Contabilidad del sistema nuevo no está lista para el paralelo (ver la nota de la sección 33 del alcance).</li><li><strong>Dirección:</strong> saliente (asientos) o entrante (importar asientos de otro sistema).</li><li><strong>Evidencia:</strong> [T] <code>SISCONT</code>; [B] <code>clsAsiento.ImportarAsientos</code>, <code>ImportarAsientosConSeccion</code>, <code>clsContabilidad.ExportarArchivos</code>.</li></ul><hr><h2 id="_19-hardware-local" tabindex="-1">19. Hardware local <a class="header-anchor" href="#_19-hardware-local" aria-label="Permalink to &quot;19. Hardware local&quot;">​</a></h2><ul><li><strong>Prioridad:</strong> C.</li><li><strong>Evidencia:</strong> [B] lectores de tarjeta con chip EMV y banda magnética (<code>clsLectorCRT603</code>, <code>clsLectorTarjetas</code>: 3nStar, PT800), lector de billetes (<code>clsLectorBilletes</code>, para cajas de autoservicio), impresora de tickets (<code>Impresoras.Masung_D347</code>), escáner (<code>clsEscaner</code>), turnero por puerto serie (<code>clsTurnero.EscucharPuerto</code>), dispensador de agua (<code>clsDispenser</code>).</li><li><strong>Nota:</strong> un sistema web no puede hablar directamente con estos dispositivos. Si alguno se usa, hace falta un pequeño agente local en la PC de la caja o del turnero. Antes de decidirlo hay que confirmar si la cooperativa usa alguno; el cobro con tarjeta se puede resolver con posnet o QR, sin lector integrado.</li></ul><hr><h2 id="_20-inteligencia-artificial" tabindex="-1">20. Inteligencia artificial <a class="header-anchor" href="#_20-inteligencia-artificial" aria-label="Permalink to &quot;20. Inteligencia artificial&quot;">​</a></h2><ul><li><strong>Prioridad:</strong> C.</li><li><strong>Evidencia:</strong> [T] <code>AUDIT_IA</code>; [B] <code>clsChatGPT</code> (OpenAI), <code>clsLeerComprobante</code> (lee facturas de proveedores en PDF con IA y propone la carga), <code>clsAnalisisNotasTicket</code>.</li><li><strong>Nota:</strong> no es imprescindible para el reemplazo, pero la lectura automática de facturas de compra es una función que los usuarios de Procoop ya conocen.</li></ul><hr><h2 id="_21-migracion-desde-procoop" tabindex="-1">21. Migración desde Procoop <a class="header-anchor" href="#_21-migracion-desde-procoop" aria-label="Permalink to &quot;21. Migración desde Procoop&quot;">​</a></h2><ul><li><strong>Prioridad:</strong> A. Se ejecuta una vez para el paralelo y otra vez para el by pass.</li><li><strong>Dirección:</strong> entrante.</li><li><strong>Fuentes:</strong><ul><li>Base SQL Server de Procoop (en la DEMO, <code>PR_LAG_DEMO</code>). El modelo completo está en <a href="./binarios/CapaDatos-tablas"><code>binarios/CapaDatos-tablas.md</code></a>.</li><li>Base MySQL del portal y de la app (usuarios web, adhesiones).</li><li>Adjuntos y PDF (carpetas del servidor y Amazon S3).</li><li>Archivos heredados en DBF, Access y Excel [B] <code>NDbfReader.dll</code>, <code>Microsoft.Office.Interop.Access.Dao</code>, <code>Importador.exe</code>.</li></ul></li><li><strong>Diseño propuesto:</strong> migración repetible y automatizada, que se pueda correr varias veces durante el paralelo con un informe de diferencias (cantidad de registros, saldos por cuenta, deuda total).</li><li><strong>Pendiente:</strong> acceso de solo lectura a la base real; política de anonimización para los ambientes de prueba (ver la advertencia del README sobre datos personales).</li></ul><hr><h2 id="_22-infraestructura-que-reemplaza-procesos-de-procoop" tabindex="-1">22. Infraestructura que reemplaza procesos de Procoop <a class="header-anchor" href="#_22-infraestructura-que-reemplaza-procesos-de-procoop" aria-label="Permalink to &quot;22. Infraestructura que reemplaza procesos de Procoop&quot;">​</a></h2><p>Varias &quot;integraciones&quot; de Procoop son en realidad tareas programadas que corren en un servicio de Windows de la cooperativa (<code>clsServicio_Procoop</code>) [B]: sincronizar el portal, transferir archivos por FTP, procesar archivos de rendición, registrar facturas electrónicas, enviar mails y WhatsApp, hacer copias de seguridad. En un sistema SaaS todo esto pasa a ser responsabilidad de la plataforma:</p><table tabindex="0"><thead><tr><th>En Procoop</th><th>En el sistema nuevo</th></tr></thead><tbody><tr><td>Servicio de Windows con tareas programadas</td><td>Procesos en segundo plano con colas y reintentos</td></tr><tr><td>Sincronización con MySQL para portal y app</td><td>Portal y app sobre la misma API</td></tr><tr><td>Transferencia por FTP (<code>TransferirFTP</code>, <code>BorrarAFTP</code>)</td><td>SFTP o API con cada ente, con registro de cada envío</td></tr><tr><td>Archivos en carpetas del servidor</td><td>Almacenamiento de objetos con control de acceso</td></tr><tr><td>Copias de seguridad hechas por el usuario</td><td>Copias automáticas gestionadas por la plataforma</td></tr></tbody></table><hr><h2 id="_23-lista-de-pedidos-a-la-cooperativa" tabindex="-1">23. Lista de pedidos a la cooperativa <a class="header-anchor" href="#_23-lista-de-pedidos-a-la-cooperativa" aria-label="Permalink to &quot;23. Lista de pedidos a la cooperativa&quot;">​</a></h2><p>Para cerrar las fichas hace falta pedirle a Laguna Larga:</p><ol><li>La lista de <strong>entes recaudadores, bancos, tarjetas y botones de pago</strong> que usa hoy, con un archivo de deuda y uno de rendición de ejemplo de cada uno, anonimizados.</li><li>El <strong>formato del código de barras</strong> de la factura y una factura impresa de muestra.</li><li>Cómo se <strong>leen los medidores</strong> (planilla, colector portátil, app o telemedición) y la marca del sistema de <strong>prepago</strong>, si lo tiene.</li><li>El <strong>padrón de subsidios</strong> vigente para energía y gas, y cómo lo recibe.</li><li>Los <strong>regímenes informativos</strong> que presenta (ARCA, Rentas Córdoba, ERSeP, ENARGAS, FECESCOR) y con qué frecuencia.</li><li>Qué <strong>tasas de terceros</strong> factura y a quién las rinde.</li><li>Si usa el <strong>portal CoopOnline</strong>, la app móvil, WhatsApp Business y SMS, y con qué proveedores.</li><li>Quién consume la <strong>API para terceros</strong> de Procoop.</li><li>Si liquida <strong>sueldos</strong> y lleva la <strong>contabilidad</strong> en Procoop o fuera de él.</li><li>Si usa algún <strong>dispositivo local</strong> en las cajas (lector de tarjetas, impresora de tickets, turnero).</li></ol>',141)])])}const m=o(t,[["render",n]]);export{p as __pageData,m as default};
